SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `plans`, `subscribers`, `billing`, `payments`, `usage_logs`, `tickets`, `churn`;
SET FOREIGN_KEY_CHECKS = 1;

-- =====================================================
-- BUSINESS CONTEXT (short)
-- A mobile telecom carrier. Tables: plans, subscribers, billing, payments, usage_logs, tickets, churn.
-- =====================================================

CREATE TABLE `plans` (
    `plan_id` VARCHAR(6) PRIMARY KEY,
    `plan_name` VARCHAR(20),
    `monthly_fee` DECIMAL(8,2),
    `data_gb` INT,
    `voice_min` INT
);

CREATE TABLE `subscribers` (
    `sub_id` INT PRIMARY KEY,
    `first_name` VARCHAR(30),
    `last_name` VARCHAR(30),
    `phone` VARCHAR(15),
    `plan_id` VARCHAR(6),
    `region` VARCHAR(15),
    `signup_date` DATE,
    `status` VARCHAR(12)
);

CREATE TABLE `billing` (
    `bill_id` INT PRIMARY KEY,
    `sub_id` INT,
    `bill_date` DATE,
    `period_start` DATE,
    `period_end` DATE,
    `amount` DECIMAL(8,2),
    `status` VARCHAR(10)
);

CREATE TABLE `payments` (
    `pay_id` INT PRIMARY KEY,
    `sub_id` INT,
    `bill_id` INT,
    `pay_date` DATE,
    `amount` DECIMAL(8,2),
    `method` VARCHAR(15)
);

CREATE TABLE `usage_logs` (
    `log_id` INT PRIMARY KEY,
    `sub_id` INT,
    `log_date` DATE,
    `data_mb` INT,
    `voice_min` INT,
    `sms` INT
);

CREATE TABLE `tickets` (
    `ticket_id` INT PRIMARY KEY,
    `sub_id` INT,
    `created_date` DATE,
    `resolved_date` DATE,
    `category` VARCHAR(15),
    `status` VARCHAR(10)
);

CREATE TABLE `churn` (
    `churn_id` INT PRIMARY KEY,
    `sub_id` INT,
    `churn_date` DATE,
    `reason` VARCHAR(25)
);

